draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // character
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();

  // arms
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 10);
  ctx.lineTo(W/2 - 30 + 20 * Math.sin(t), H/2 + 50);
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 10);
  ctx.lineTo(W/2 + 30 + 20 * Math.sin(t), H/2 + 50);
  ctx.stroke();

  // legs
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 30);
  ctx.lineTo(W/2 - 20 + 15 * Math.sin(t), H/2 + 70);
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 30);
  ctx.lineTo(W/2 + 20 + 15 * Math.sin(t), H/2 + 70);
  ctx.stroke();

  // grit text
  ctx.font = '24px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.fillStyle = 'black';
  ctx.fillText('Grit', W/2, H/2 - 50 + 10 * Math.sin(t));

  // passion text
  ctx.fillText('Passion', W/2, H/2 - 20 + 10 * Math.cos(t));

  // perseverance text
  ctx.fillText('Perseverance', W/2, H/2 + 10 + 10 * Math.sin(t));

  // angela duckworth text
  ctx.font = '18px Arial';
  ctx.fillText('Angela Duckworth', W/2, H - 20);

  ctx.restore();
}
